package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="integration_request_logs") public class IntegrationRequestLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="request_id") private String requestId; @Column(name="integration_name") private String integrationName; private String endpoint; @Column(name="http_method") private String httpMethod; @Column(name="external_reference") private String externalReference; @Column(name="request_timestamp") private Instant requestTimestamp; @Column(name="response_timestamp") private Instant responseTimestamp; @Column(name="http_status") private Integer httpStatus; private boolean success; @Column(name="error_code") private String errorCode; @Column(name="error_message") private String errorMessage; public void setRequestId(String v){requestId=v;} public void setIntegrationName(String v){integrationName=v;} public void setEndpoint(String v){endpoint=v;} public void setHttpMethod(String v){httpMethod=v;} public void setExternalReference(String v){externalReference=v;} public void setRequestTimestamp(Instant v){requestTimestamp=v;} public void setResponseTimestamp(Instant v){responseTimestamp=v;} public void setHttpStatus(Integer v){httpStatus=v;} public void setSuccess(boolean v){success=v;} public void setErrorCode(String v){errorCode=v;} public void setErrorMessage(String v){errorMessage=v;}
public Long getId(){return id;} public String getRequestId(){return requestId;} public String getIntegrationName(){return integrationName;} public String getEndpoint(){return endpoint;} public String getHttpMethod(){return httpMethod;} public String getExternalReference(){return externalReference;} public Instant getRequestTimestamp(){return requestTimestamp;} public Instant getResponseTimestamp(){return responseTimestamp;} public Integer getHttpStatus(){return httpStatus;} public boolean isSuccess(){return success;} public String getErrorCode(){return errorCode;} public String getErrorMessage(){return errorMessage;} }
